/**
 * The types `save/events/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    EventRecordSaveRow, EventRecordRelic, EventRelicRow, EventRelicSet, EventsSaveExtract, EventShopThemeRow, EventShopRelicRow, EventShopSongRow (+1 more)
 * depends    src/data/events/types
 * used by    src/save/events/index, src/save/events/read, src/save/events/relic-sets, src/save/events/shop
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { EventShopCurrency, EventShopPrice } from '../../data/events/types'

/** One event the player took part in. */
export interface EventRecordSaveRow {
  number: number | null
  /**
   * The date the save records for the event, ISO. Not the start: a v29.2 export dates the running
   * Rainfall event 2026-11-18T03:13Z, a day after the account already held 520 of its medals, so
   * it reads as the last update.
   */
  date: string | null
  /** The game's internal event name (`RAINFALL`), or null where older records left it blank. */
  name: string | null
  medals: number | null
  medalsSpent: number | null
  /** Relic indices unlocked during the event, as `relicsUnlocked` numbers them. */
  relicsUnlocked: number[]
  /** The same relics by name, in the same order. */
  relics: EventRecordRelic[]
  /**
   * The event as the game's relic text spells it ("Rainfall"), or null when no relic names it. A
   * rerun the save names after its tower theme (`HOWLING_WOLF`) reads as the original ("Full Moon").
   */
  event: string | null
}

/** A relic an event record lists, named. */
export interface EventRecordRelic {
  index: number
  /** Display name, or null for a relic index this package cannot name. */
  label: string | null
}

/** One relic an event awards. */
export interface EventRelicRow {
  /** Save index: the relic's position in `relicsUnlocked`. */
  index: number
  label: string
  rarity: string | null
  /** The stat the relic adds to, by the game's name. */
  stat: string | null
  /** As stored: a fraction for a percentage, metres for BotRange. */
  benefit: number | null
  /**
   * Medals to EARN during the event to be given the relic. Not what the event shop charges for
   * it: that is `shopPrice`.
   */
  medals: number | null
  /** True for the 550 and 1100 medal relics, which also need that event's pass. */
  needsEventPass: boolean | null
  /** What the event shop charges for it in medals when its event reruns, by rarity. */
  shopPrice: EventShopPrice | null
  /** What the shop charges in gems when it is on the Rotating Relics shelf, by rarity. */
  rotatingShopPrice: EventShopPrice | null
}

/** An event and the relics it awards. */
export interface EventRelicSet {
  /** The event as the game's relic text spells it. */
  event: string
  /** The name lower-cased with punctuation and spaces removed, for matching a save's spelling. */
  key: string
  relics: EventRelicRow[]
}

export interface EventsSaveExtract {
  lastEventNumber: number | null
  /** Medals earned in the current event. */
  medalsCurrentEvent: number | null
  /** Events, oldest first. */
  records: EventRecordSaveRow[]
  warnings: string[]
}

/** A theme the current event's shop sells. */
export interface EventShopThemeRow {
  kind: 'tower' | 'background'
  name: string
  price: number
  currency: EventShopCurrency
  /** Passive coin bonus for owning it, as the game shows it ("+0.4%"). */
  coinBonus: string
}

/** A relic of the current event, at the price the shop sells it for. */
export interface EventShopRelicRow {
  index: number
  label: string
  rarity: string | null
  price: number | null
  currency: EventShopCurrency | null
  /** Medals to earn in the event to be given it instead of buying it. */
  earnThreshold: number | null
  /** Whether the save already holds it. Null for a save with no relic data. */
  owned: boolean | null
}

/** A song the shop sells in every event. */
export interface EventShopSongRow {
  name: string
  price: number
  currency: EventShopCurrency
  coinBonus: string
}

/** The current event's shop: what it sells and for how much. */
export interface EventShopSaveExtract {
  /** The event as the game's relic text spells it, or null when the save's name matches nothing here. */
  event: string | null
  /** The event name as the save writes it (`HOWLING_WOLF`). */
  saveName: string | null
  eventNumber: number | null
  /** Medals earned in the current event; not the spendable balance. */
  medalsCurrentEvent: number | null
  themes: EventShopThemeRow[]
  relics: EventShopRelicRow[]
  /**
   * Prices of the Rotating Relics shelf by rarity. The save does not record which relics are on
   * the shelf, so only the prices can be stated.
   */
  rotatingRelicPrices: { rarity: string, price: number, currency: EventShopCurrency }[]
  songs: EventShopSongRow[]
  warnings: string[]
}
